vec4 transition(vec2 uv) {
  return mix(getFromColor(uv), getToColor(uv), smoothstep(0.0, 1.0, progress));
}

vec4 transition(vec2 uv) {
  float a = smoothstep(0.0, 0.5, progress);
  float b = smoothstep(0.5, 1.0, progress);
  return mix(mix(getFromColor(uv), vec4(0.0, 0.0, 0.0, 1.0), a), getToColor(uv), b);
}

vec4 transition(vec2 uv) {
  float a = smoothstep(0.0, 0.5, progress);
  float b = smoothstep(0.5, 1.0, progress);
  return mix(mix(getFromColor(uv), vec4(1.0), a), getToColor(uv), b);
}

uniform vec2 direction; // = vec2(1.0, 0.0)
uniform float softness; // = 0.08
vec4 transition(vec2 uv) {
  vec2 n = normalize(direction);
  float h = 0.5 * (abs(n.x) + abs(n.y));
  float along = (dot(uv - 0.5, n) + h) / (2.0 * h);
  float edge = progress * (1.0 + softness) - softness;
  float m = smoothstep(edge, edge + softness, along);
  return mix(getToColor(uv), getFromColor(uv), m);
}

