uniform vec2 direction; // = vec2(-1.0, 0.0)
vec4 transition(vec2 uv) {
  float p = smoothstep(0.0, 1.0, progress);
  vec2 uf = uv - direction * p;
  vec2 ut = uv - direction * (p - 1.0);
  bool inFrom = uf.x >= 0.0 && uf.x <= 1.0 && uf.y >= 0.0 && uf.y <= 1.0;
  return inFrom ? getFromColor(uf) : getToColor(ut);
}

