vec4 transition(vec2 uv) {
  vec2 c = vec2(0.5);
  float p = smoothstep(0.0, 1.0, progress);
  float zf = 1.0 + p * 1.2;
  float zt = 2.2 - p * 1.2;
  vec4 a = getFromColor(c + (uv - c) / zf);
  vec4 b = getToColor(c + (uv - c) / zt);
  return mix(a, b, smoothstep(0.35, 0.65, p));
}

vec4 transition(vec2 uv) {
  vec2 c = vec2(0.5);
  float strength = sin(progress * 3.14159265) * 0.18;
  vec4 a = vec4(0.0);
  vec4 b = vec4(0.0);
  for (int i = 0; i < 12; i++) {
    float t = float(i) / 11.0;
    vec2 s = c + (uv - c) * (1.0 - strength * t);
    a += getFromColor(s);
    b += getToColor(s);
  }
  return mix(a / 12.0, b / 12.0, smoothstep(0.35, 0.65, progress));
}

vec4 transition(vec2 uv) {
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float reach = length(vec2(ratio, 1.0) * 0.5);
  float r = progress * reach * 1.05;
  float m = smoothstep(r, r - 0.03, length(p));
  return mix(getFromColor(uv), getToColor(uv), m);
}

vec4 transition(vec2 uv) {
  vec2 d = uv - 0.5;
  float angle = atan(d.x, -d.y);
  float a = (angle + 3.14159265) / 6.2831853;
  float m = step(a, progress);
  return mix(getFromColor(uv), getToColor(uv), m);
}

uniform float slats; // = 10.0
vec4 transition(vec2 uv) {
  float m = step(fract(uv.x * slats), progress);
  return mix(getFromColor(uv), getToColor(uv), m);
}

uniform float blocks; // = 48.0
vec4 transition(vec2 uv) {
  float amount = sin(progress * 3.14159265);
  float size = mix(1.0, blocks, amount);
  vec2 grid = vec2(size * ratio, size);
  vec2 q = amount > 0.01 ? (floor(uv * grid) + 0.5) / grid : uv;
  return mix(getFromColor(q), getToColor(q), smoothstep(0.4, 0.6, progress));
}

float rnd(vec2 s) {
  return fract(sin(dot(s, vec2(12.9898, 78.233))) * 43758.5453);
}
vec4 transition(vec2 uv) {
  float amount = sin(progress * 3.14159265);
  float row = floor(uv.y * 24.0);
  float shake = (rnd(vec2(row, floor(progress * 14.0))) - 0.5) * 0.22 * amount;
  vec2 u = uv + vec2(shake, 0.0);
  float split = 0.012 * amount;
  vec4 a = vec4(getFromColor(u + vec2(split, 0.0)).r, getFromColor(u).g, getFromColor(u - vec2(split, 0.0)).b, 1.0);
  vec4 b = vec4(getToColor(u + vec2(split, 0.0)).r, getToColor(u).g, getToColor(u - vec2(split, 0.0)).b, 1.0);
  float cut = progress + (rnd(vec2(row, 3.0)) - 0.5) * 0.3 * amount;
  return mix(a, b, step(0.5, cut));
}

vec4 transition(vec2 uv) {
  float p = smoothstep(0.0, 1.0, progress);
  float blur = sin(progress * 3.14159265) * 0.12;
  vec4 a = vec4(0.0);
  vec4 b = vec4(0.0);
  for (int i = 0; i < 12; i++) {
    float t = float(i) / 11.0 - 0.5;
    vec2 sa = vec2(uv.x - p + t * blur, uv.y);
    vec2 sb = vec2(uv.x - p + 1.0 + t * blur, uv.y);
    a += getFromColor(fract(sa));
    b += getToColor(fract(sb));
  }
  a /= 12.0;
  b /= 12.0;
  return (uv.x - p >= 0.0) ? a : b;
}

vec4 transition(vec2 uv) {
  float p = smoothstep(0.0, 1.0, progress);
  vec2 c = vec2(0.5);
  vec2 d = (uv - c) * vec2(ratio, 1.0);
  float turn = p * 1.2;
  float cs = cos(turn);
  float sn = sin(turn);
  vec2 r = vec2(cs * d.x - sn * d.y, sn * d.x + cs * d.y);
  float z = 1.0 + p * 0.8;
  vec2 sa = c + (r / z) / vec2(ratio, 1.0);
  float zb = 1.8 - p * 0.8;
  vec2 rb = vec2(cs * d.x + sn * d.y, -sn * d.x + cs * d.y);
  vec2 sb = c + (rb / zb) / vec2(ratio, 1.0);
  return mix(getFromColor(sa), getToColor(sb), smoothstep(0.4, 0.6, p));
}

vec4 transition(vec2 uv) {
  float l = dot(getFromColor(uv).rgb, vec3(0.299, 0.587, 0.114));
  float th = progress * 1.3 - 0.15;
  float m = smoothstep(th - 0.12, th + 0.12, l);
  return mix(getToColor(uv), getFromColor(uv), m);
}

float hash(vec2 p) {
  p = fract(p * vec2(443.897, 441.423));
  p += dot(p, p.yx + 19.19);
  return fract((p.x + p.y) * p.x);
}
vec4 transition(vec2 uv) {
  float n = hash(floor(uv * vec2(ratio, 1.0) * 90.0));
  float m = smoothstep(n - 0.06, n + 0.06, progress * 1.3 - 0.12);
  return mix(getFromColor(uv), getToColor(uv), m);
}

vec4 transition(vec2 uv) {
  vec2 c = vec2(0.5);
  vec2 d = (uv - c) * vec2(ratio, 1.0);
  float dist = length(d);
  float amount = sin(progress * 3.14159265) * 5.0 * (1.0 - smoothstep(0.0, 0.8, dist));
  float cs = cos(amount);
  float sn = sin(amount);
  vec2 r = vec2(cs * d.x - sn * d.y, sn * d.x + cs * d.y) / vec2(ratio, 1.0) + c;
  return mix(getFromColor(r), getToColor(r), smoothstep(0.35, 0.65, progress));
}

vec4 transition(vec2 uv) {
  vec2 d = uv - 0.5;
  float dist = length(d * vec2(ratio, 1.0));
  vec2 off = normalize(d + vec2(0.00001)) * sin(dist * 42.0 - progress * 22.0) * 0.028 * sin(progress * 3.14159265);
  return mix(getFromColor(uv + off), getToColor(uv + off), smoothstep(0.3, 0.7, progress));
}

vec4 transition(vec2 uv) {
  float m = step(abs(uv.x - 0.5) * 2.0, progress);
  return mix(getFromColor(uv), getToColor(uv), m);
}

vec4 transition(vec2 uv) {
