vec4 transition(vec2 uv) {
  float p = progress;
  float k = p < 0.5 ? 1.0 - p * 2.0 : (p - 0.5) * 2.0;
  vec2 u = vec2(uv.x, 0.5 + (uv.y - 0.5) / max(k, 0.0001));
  bool inside = u.y >= 0.0 && u.y <= 1.0;
  vec4 c = p < 0.5 ? getFromColor(u) : getToColor(u);
  return inside ? c : vec4(0.0, 0.0, 0.0, 1.0);
}

vec4 transition(vec2 uv) {
  float s = abs(cos(progress * 3.14159265));
  vec2 u = vec2(0.5 + (uv.x - 0.5) / max(s, 0.0001), uv.y);
  bool inside = u.x >= 0.0 && u.x <= 1.0;
  vec4 c = progress < 0.5 ? getFromColor(u) : getToColor(u);
  return inside ? vec4(c.rgb * mix(0.55, 1.0, s), 1.0) : vec4(0.0, 0.0, 0.0, 1.0);
}

