vec4 transition(vec2 uv) {
  float p = smoothstep(0.0, 1.0, progress);
  vec2 ut = uv - direction * (p - 1.0);
  bool inTo = ut.x >= 0.0 && ut.x <= 1.0 && ut.y >= 0.0 && ut.y <= 1.0;
  return inTo ? getToColor(ut) : getFromColor(uv);
}

