vec4 transition(vec2 uv) {
  float flash = sin(progress * 3.14159265);
  vec3 base = mix(getFromColor(uv).rgb, getToColor(uv).rgb, smoothstep(0.4, 0.6, progress));
  float band = 0.6 + 0.4 * sin(uv.x * 5.0 + progress * 9.0) * sin(uv.y * 3.0 - progress * 4.0);
  vec3 burn = vec3(1.0, 0.55, 0.18) * flash * 1.25 * band;
  return vec4(1.0 - (1.0 - base) * (1.0 - clamp(burn, 0.0, 1.0)), 1.0);
}

float hash(vec2 p) {
  p = fract(p * vec2(443.897, 441.423));
  p += dot(p, p.yx + 19.19);
  return fract((p.x + p.y) * p.x);
}
vec4 transition(vec2 uv) {
  vec2 g = floor(uv * vec2(16.0 * ratio, 16.0));
  float n = hash(g);
  float m = smoothstep(n - 0.08, n + 0.08, progress * 1.3 - 0.12);
  return mix(getFromColor(uv), getToColor(uv), m);
}

vec4 transition(vec2 uv) {
  float row = floor(uv.y * 8.0);
  float d = mod(row, 2.0) < 1.0 ? 1.0 : -1.0;
  float p = smoothstep(0.0, 1.0, progress);
  vec2 uf = uv - vec2(d * p, 0.0);
  bool inFrom = uf.x >= 0.0 && uf.x <= 1.0;
  return inFrom ? getFromColor(uf) : getToColor(uv);
}

vec4 transition(vec2 uv) {
  float amount = sin(progress * 3.14159265) * 0.035;
  vec4 a = vec4(0.0);
  vec4 b = vec4(0.0);
  for (int i = 0; i < 14; i++) {
    float ang = float(i) * 2.39996323;
    float rr = sqrt((float(i) + 0.5) / 14.0);
    vec2 o = vec2(cos(ang), sin(ang)) * rr * amount;
    a += getFromColor(uv + o);
    b += getToColor(uv + o);
  }
  return mix(a / 14.0, b / 14.0, smoothstep(0.3, 0.7, progress));
}
